/**
 * Handles boundary adjustments based on comparison results.
 * Defines the behavior of how low/high bounds change during search.
 */
interface BoundaryHandler {
    /**
     * Process comparison and adjust bounds.
     *
     * @param comparison result of comparison (0, <0, >0)
     * @param mid the middle index
     * @return true if match found and should stop, false to continue
     */
    boolean handleComparison(int comparison, int mid);
}

/**
 * Handler for standard binary search - stops at first match.
 */
class StandardBoundaryHandler implements BoundaryHandler {
    private int low;
    private int high;
    private int result = -1;

    StandardBoundaryHandler(int low, int high) {
        this.low = low;
        this.high = high;
    }

    @Override
    public boolean handleComparison(int comparison, int mid) {
        if (comparison == 0) {
            result = mid;
            return true;
        } else if (comparison < 0) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
        return false;
    }

    int getLow() {
        return low;
    }

    int getHigh() {
        return high;
    }

    int getResult() {
        return result;
    }

    boolean isValid() {
        return low <= high;
    }
}

/**
 * Handler for finding first occurrence - continues left after match.
 */
class FirstOccurrenceBoundaryHandler implements BoundaryHandler {
    private int low;
    private int high;
    private int result = -1;

    FirstOccurrenceBoundaryHandler(int low, int high) {
        this.low = low;
