    /**
     * Process comparison result and update bounds.
     *
     * @param comparison result of comparison (0, <0, >0)
     * @param mid current middle index
     */
    void processBoundary(int comparison, int mid);

    /**
     * Get the final result index.
     *
     * @return the index to return, or -1 if not found
     */
    int getResult();

    /**
     * Check if search should continue.
     *
     * @return true if there are more elements to search
     */
    boolean isValid();
}

/**
 * Abstract base strategy consolidating common behavior.
 */
abstract class BaseSearchStrategy<T extends Comparable<T>> implements SearchStrategy<T> {
    protected final BoundaryHandler handler;

    protected BaseSearchStrategy(BoundaryHandler handler) {
        this.handler = handler;
    }

    @Override
    public void processBoundary(int comparison, int mid) {
        handler.handleComparison(comparison, mid);
    }

    @Override
    public int getResult() {
        if (handler instanceof StandardBoundaryHandler) {
            return ((StandardBoundaryHandler) handler).getResult();
        } else if (handler instanceof FirstOccurrenceBoundaryHandler) {
            return ((FirstOccurrenceBoundaryHandler) handler).getResult();
        } else if (handler instanceof LastOccurrenceBoundaryHandler) {
            return ((LastOccurrenceBoundaryHandler) handler).getResult();
        }
        return -1;
    }

    @Override
    public boolean isValid() {
        if (handler instanceof StandardBoundaryHandler) {
            return ((StandardBoundaryHandler) handler).isValid();
