    public boolean handleComparison(int comparison, int mid) {
        if (comparison == 0) {
            result = mid;
            low = mid + 1;
        } else if (comparison < 0) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
        return false;
    }

    int getLow() {
        return low;
    }

    int getHigh() {
        return high;
    }

    int getResult() {
        return result;
    }

    boolean isValid() {
        return low <= high;
    }
}

